// Vem do Inbox do LiveOps: {conv:'cw_123', texto, autor:'CM'|'Gustavo'|...}
const b = $json.body || $json;
const texto = String(b.texto || '').trim().slice(0, 4000);
const conv = String(b.conv || '');
const num = conv.replace(/^cw_/, '');
if (!texto || !/^\d+$/.test(num)) return [];
const quem = String(b.autor || '').trim() || '?';
const ts = Date.now();
// O CLIENTE ve sempre a persona da empresa; o registro interno guarda quem
// realmente mandou (Manoel (CM), Manoel (Gustavo)...), gravado direto no
// Firebase pelos mesmos nos Gravar — o eco do Chatwoot e descartado no
// Mapear mensagem para nao duplicar o balao.
return [{ json: {
  convNum: num,
  corpo: { content: '*Manoel - Suplelive:*\n' + texto, message_type: 'outgoing', private: false },
  convId: conv,
  msgId: 'ls' + ts,
  conv: { id: conv, ultima: texto.slice(0, 120), deUltima: 'agente', ts },
  msg:  { texto, de: 'agente', autor: 'Manoel (' + quem + ')', ts }
} }];

// O que vira registro no LiveOps. Tres coisas passam por aqui:
//   · mensagem do cliente        -> de:'cliente'
//   · resposta do atendente      -> de:'agente'
//   · NOTA INTERNA (cadeado)     -> de:'nota'
// A nota entra porque e assim que o envio de template pelo Gupshup fica
// registrado no Chatwoot — descartando-a, a conversa inteira ficava
// invisivel no LiveOps quando o template era o unico movimento dela.
// Fora: evento de sistema e payload sem conteudo.
const b = $json.body || $json;
if ((b.event || '') !== 'message_created') return [];
const mt = b.message_type;
const deCliente = mt === 'incoming' || mt === 0;
const ehTemplate = mt === 'template' || mt === 3;
const deAgente  = mt === 'outgoing' || mt === 1 || ehTemplate;
if (!deCliente && !deAgente) return [];   // atividade do sistema
const privada = b.private === true;

const conv = b.conversation || {};
const convNum = conv.display_id || conv.id || b.conversation_id;
if (!convNum) return [];
const convId = 'cw_' + convNum;

const contato = (conv.meta && conv.meta.sender) || {};
const nome = contato.name || (deCliente && b.sender && b.sender.name) || 'Contato';
const telefone = String(contato.phone_number || '').trim();

let texto = String(b.content || '').trim();
// Os anexos viajam com a URL: e assim que o audio toca e a imagem
// aparece (e baixa) dentro do LiveOps, em vez de virar um [imagem] seco.
const brutos = Array.isArray(b.attachments) ? b.attachments : [];
const anexos = brutos.map(a => ({
  tipo: String(a.file_type || 'file'),
  url: String(a.data_url || a.file_url || ''),
  mini: String(a.thumb_url || ''),
  nome: String(a.file_name || ''),
})).filter(a => a.url);
if (!texto && brutos.length) {
  const tipos = { image: 'imagem', audio: 'audio', video: 'video', file: 'arquivo' };
  texto = '[' + (tipos[brutos[0].file_type] || 'anexo') + ']';
}
if (!texto && !anexos.length) return [];

// Resposta enviada pelo LiveOps volta como eco do Chatwoot com a assinatura
// da persona — ja foi gravada com o autor interno na hora do envio; aqui e
// descartada para nao duplicar o balao.
if (deAgente && !privada && texto.indexOf('*Manoel - Suplelive:*') === 0) return [];

// Comando interno do canal (ex.: /iniciar_atendimento) nao vira balao.
if (deAgente && !privada && texto[0] === '/') return [];

let ts = b.created_at ? (typeof b.created_at === 'number' ? b.created_at : Date.parse(b.created_at)) : Date.now();
if (ts && ts < 1e12) ts = ts * 1000;   // Chatwoot as vezes manda em segundos

// Quem escreveu: persona + quem digitou, para o controle interno
const quem = (((b.sender && b.sender.name) || '?').trim().split(/\s+/)[0]);
const autor = privada ? quem : (deAgente ? ('Manoel (' + quem + ')') : '');
const caixa = (b.inbox && b.inbox.name) || '';
const de = privada ? 'nota' : (deAgente ? 'agente' : 'cliente');

return [{ json: {
  convId,
  msgId: 'm' + (b.id || ts),
  conv: { id: convId, nome, telefone, caixa, ultima: texto.slice(0, 120), deUltima: de, ts },
  msg:  { texto: texto.slice(0, 4000), de, autor, ts,
          anexos: anexos.length ? anexos.slice(0, 6) : undefined }
} }];

// Vem do formulario Novo Contato do LiveOps: {nome, telefone:'+55...', email, cpf}
const b = $json.body || $json;
const nome = String(b.nome || '').trim();
if (!nome) return [];
const tel = String(b.telefone || '').trim();
const email = String(b.email || '').trim();
const cpf = String(b.cpf || '').replace(/\D/g, '');
if (!tel && !email) return [];
const contato = { name: nome };
if (tel) contato.phone_number = tel;
if (email) contato.email = email;
// CPF entra como atributo do contato (crie o atributo 'cpf' em
// Configuracoes > Atributos Personalizados > Contato para ele aparecer)
if (cpf) contato.custom_attributes = { cpf };
return [{ json: { contato } }];

// Id da caixa de entrada do WhatsApp no Chatwoot (1. Oficial).
// Se mudar de caixa um dia: Configuracoes > Caixas de Entrada — e o numero no fim da URL.
const INBOX_ID = 9;
const b = $json.body || $json;
const texto = String(b.texto || '').trim().slice(0, 4000);
const telefone = String(b.telefone || '').trim();
const dig = telefone.replace(/\D/g, '');
if (!texto || dig.length < 10) return [];
if (!INBOX_ID) throw new Error('Preencha o INBOX_ID neste no (id da caixa 1. Oficial).');
return [{ json: { texto, telefone, dig, nome: String(b.nome || '').trim(),
  autor: String(b.autor || '').trim() || '?', inboxId: INBOX_ID } }];

const prep = $('Preparar nova conversa').first().json;
const lista = ($json.payload || $json.contacts || []);
const fim = prep.dig.slice(-8);
let contato = lista.find(c => String(c.phone_number || '').replace(/\D/g, '').endsWith(fim));
if (!contato && lista.length === 1) contato = lista[0];
if (!contato) throw new Error('Contato ' + prep.telefone + ' nao existe no Chatwoot — cadastre-o primeiro (o formulario de Clientes ja faz isso).');
const ci = (contato.contact_inboxes || []).find(x => x.inbox && x.inbox.id === prep.inboxId);
return [{ json: { ...prep, contactId: contato.id, sourceId: ci ? ci.source_id : '' } }];

const prev = $('Resolver contato').first().json;
const r = $json || {};
const sourceId = prev.sourceId || r.source_id || (r.payload && r.payload.source_id) || '';
if (!sourceId) throw new Error('Sem source_id para abrir a conversa — confira o INBOX_ID no no Preparar nova conversa.');
return [{ json: { ...prev, sourceId } }];

const prep = $('Consolidar canal').first().json;
const conv = $('Criar conversa').first().json || {};
const num = conv.display_id || conv.id;
if (!num) throw new Error('Chatwoot nao devolveu o id da conversa nova.');
const ts = Date.now();
return [{ json: {
  convNum: String(num),
  corpo: { content: '*Manoel - Suplelive:*\n' + prep.texto, message_type: 'outgoing', private: false },
  convId: 'cw_' + num,
  msgId: 'ls' + ts,
  conv: { id: 'cw_' + num, nome: prep.nome || 'Contato', telefone: prep.telefone, caixa: '',
          ultima: prep.texto.slice(0, 120), deUltima: 'agente', ts },
  msg:  { texto: prep.texto, de: 'agente', autor: 'Manoel (' + prep.autor + ')', ts }
} }];

// Devolve para o LiveOps so o que a tela precisa: nome e telefone.
const lista = ($json.payload || []);
const contatos = lista.slice(0, 12)
  .map(c => ({ nome: c.name || 'Contato', telefone: String(c.phone_number || '').trim() }))
  .filter(c => c.telefone);
return [{ json: { contatos } }];

// O comando /iniciar_atendimento abre o canal no WhatsApp; a pausa
// da tempo de ele ser processado antes da mensagem de verdade sair.
await new Promise(r => setTimeout(r, 2000));
return [$('Criar conversa').first()];
